export async function execute(args = {}) {
  const lines = String(args.csv || '').trim().split(/\r?\n/).slice(1)
  const min = Number(args.min)
  const rows = lines.map((l) => l.split(',').map((x) => x.trim())).filter((r) => Number(r[1]) >= min)
  return { rows, count: rows.length }
}

import test from 'node:test'
import assert from 'node:assert'
import { execute } from '../lib/impl.js'
test('filter', async () => {
  const r = await execute({ csv: 'name,value\na,1\nb,5\nc,3', min: 3 })
  assert.equal(r.count, 2)
})
